//! The core tomllib port (`services::pytoml`, which replaced workstream B's private port at the merge: PORTING.md A-7) against
//! CPython 3.13 tomllib on the same documents
//! (tests/fixtures/openshell/tomllib_golden.json, generated by tests/fixtures/openshell/gen_tomllib_golden.py): values,
//! error classes and `str(e)` texts with their line/column suffix.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::needless_pass_by_value
)]

use nemo_console::services::pyfmt::float_repr;
use nemo_console::services::pytoml::{self as tomllib, TomlVal as Tv};
use serde_json::{Value, json};

fn canon(v: &Tv) -> Value {
    match v {
        Tv::Bool(b) => json!(["bool", b]),
        Tv::Int(i) => json!(["int", i.to_string()]),
        Tv::BigInt(s) => json!(["int", s]),
        Tv::Float(f) => json!(["float", float_repr(*f)]),
        Tv::Str(s) => json!(["str", s]),
        Tv::DateTime(..) => json!(["datetime", v.py_str()]),
        Tv::Date(_) => json!(["date", v.py_str()]),
        Tv::Time(_) => json!(["time", v.py_str()]),
        Tv::Array(a) => json!(["array", a.iter().map(canon).collect::<Vec<_>>()]),
        Tv::Table(t) => json!([
            "table",
            t.iter()
                .map(|(k, x)| json!([k, canon(x)]))
                .collect::<Vec<_>>()
        ]),
    }
}

fn check(cases: &[Value]) -> Vec<String> {
    let mut failures = Vec::new();
    for case in cases {
        let text = case["text"].as_str().unwrap();
        match (
            tomllib::loads(text).map(Tv::Table),
            case.get("value"),
            case.get("error"),
        ) {
            (Ok(v), Some(want), None) if &canon(&v) == want => {}
            (Err(e), None, Some(want))
                if e.class() == want["class"] && e.to_string() == want["str"] => {}
            (got, _, _) => failures.push(format!("{text:?}: got {got:?}, want {case}")),
        }
    }
    failures
}

#[test]
fn tomllib_port_matches_cpython() {
    let p = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/openshell/tomllib_golden.json"
    );
    let g: Value = serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap();
    let mut failures = check(g["cases"].as_array().unwrap());
    failures.extend(check(g["fuzz"].as_array().unwrap()));
    assert!(
        failures.is_empty(),
        "{} mismatch(es):\n{}",
        failures.len(),
        failures.join("\n")
    );
}
